head.script:
/**
 * @event
 * @name scwin.btn_layerClose_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_layerClose_onclick = function () {
    // 연 쪽(부모)이 닫는다 — 부모 스코프($c.win.getParent) 경유 id 닫기, 폴백 = 자기 닫기($c.win.closePopup).
    var id = 'jldfil11060_layer_layer1';
    try { var pa = (typeof $c !== 'undefined' && $c.win && $c.win.getParent) ? $c.win.getParent() : null; if (pa && pa.closePopup) { pa.closePopup(id); return; } } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'layerClose' }); }
    try { if (typeof $c !== 'undefined' && $c.win && $c.win.closePopup) $c.win.closePopup(); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'layerClose' }); }
};
/**
 * @event
 * @name scwin.btnDel_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.btnDel_onclick = function () { try { var pp = (typeof $c !== 'undefined' && $c.win && $c.win.getParent) ? $c.win.getParent() : null; var w = pp && pp.getWindow ? pp.getWindow() : null; var f = (w && w.scwin && w.scwin.btnDel_onclick) || (pp && pp.scwin && pp.scwin.btnDel_onclick) || (pp && pp.btnDel_onclick); if (f) return f.apply(w ? w.scwin : (pp.scwin || pp), arguments); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'jldfil11060.layerProxy.btnDel_onclick' }); } };
